1	// This file implements lossless archiving of one organization's audit
2	// export. AuditExport hands back detached in-memory records and the caller
3	// separately retains the checkpoint pinning them; an archive serializes the
4	// export so it can be saved to a file when the service instance ends and
5	// read back later, still paired with the caller's own checkpoint and still
6	// usable as the material for RecheckDecisionOffline.
7	//
8	// The format is a length-delimited binary encoding built by hand rather
9	// than encoding/json: JSON text cannot carry bytes that are not valid
10	// UTF-8 without silently replacing them with U+FFFD, which would collapse
11	// genuinely different content (a lone 0xFF, a lone 0xFE and a real U+FFFD)
12	// onto identical records and change their fingerprints. Every string is
13	// written from its exact bytes with a length prefix, and nil slices,
14	// non-nil empty slices and absent payloads are each marked explicitly.
15	//
16	// Integrity never comes from trust in the file. A decode reconstructs the
17	// records and then runs the same whole-material VerifyAudit chain check
18	// against the checkpoint the caller supplies independently; the checkpoint
19	// embedded in the archive is informational only and never authoritative.
20	package darksafe
21	
22	import (
23		"bytes"
24		"crypto/sha256"
25		"encoding/binary"
26		"errors"
27		"fmt"
28	)
29	
30	// ErrInvalidArchive means archive bytes are not a recognizable, complete,
31	// untampered audit archive: a foreign/truncated/trailing-byte framing, a
32	// failed checksum, or content that does not decode. Content-level failures
33	// (missing or mismatched organization, missing, out-of-order or modified
34	// records, a mismatched checkpoint) keep using ErrMissingOrganization and
35	// ErrInvalidRange exactly as the other audit entry points do.
36	var ErrInvalidArchive = errors.New("darksafe: invalid audit archive")
37	
38	// Archive framing:
39	//
40	//	magic   = archiveMagic
41	//	u32 BE  = byte length of the payload that follows
42	//	payload = archivePayloadLen bytes
43	//	32 bytes = SHA-256 checksum of payload
44	//
45	// A second archive concatenated to a first is trailing material, not a
46	// second frame: a read consumes exactly one frame and rejects any byte
47	// beyond it.
48	const archiveMagic = "darksafe-audit-archive-v1\n"
49	
50	const (
51		archiveTagBoolFalse byte = 0
52		archiveTagBoolTrue  byte = 1
53		archiveTagNil       byte = 0
54		archiveTagPresent   byte = 1
55	)
56	
57	// archiveWriter appends length-delimited fields to a byte buffer.
58	type archiveWriter struct {
59		buf []byte
60		err error
61	}
62	
63	func (w *archiveWriter) raw(data []byte) {
64		w.buf = append(w.buf, data...)
65	}
66	
67	// u32 writes a non-negative int as a big-endian uint32.
68	func (w *archiveWriter) u32(v int) {
69		if v < 0 || uint64(v) > 0xffffffff {
70			w.err = fmt.Errorf("%w: length out of range: %d", ErrInvalidArchive, v)
71			return
72		}
73		var b [4]byte
74		binary.BigEndian.PutUint32(b[:], uint32(v))
75		w.buf = append(w.buf, b[:]...)
76	}
77	
78	func (w *archiveWriter) boolean(v bool) {
79		if v {
80			w.buf = append(w.buf, archiveTagBoolTrue)
81		} else {
82			w.buf = append(w.buf, archiveTagBoolFalse)
83		}
84	}
85	
86	// stringField writes a string from its exact memory bytes. Nothing is
87	// validated, replaced or normalized: a lone 0xFF reaches the output as
88	// itself and stays distinguishable from 0xFE and a genuine U+FFFD.
89	func (w *archiveWriter) stringField(s string) {
90		w.u32(len(s))
91		if w.err != nil {
92			return
93		}
94		w.buf = append(w.buf, s...)
95	}
96	
97	// stringList preserves the slice shape explicitly: nil is one marker, a
98	// non-nil list is a marker, a count and the raw strings.
99	func (w *archiveWriter) stringList(items []string) {
100		if items == nil {
101			w.buf = append(w.buf, archiveTagNil)
102			return
103		}
104		w.buf = append(w.buf, archiveTagPresent)
105		w.u32(len(items))
106		for _, s := range items {
107			w.stringField(s)
108		}
109	}
110	
111	// policy writes one Policy by walking the single policy field table, so the
112	// archive's field order is the fingerprint's order by construction. Even the
113	// fingerprint-optional ResourceID is always written here (empty included),
114	// so every field round trips on its own; its placement is fixed by the
115	// table and therefore cannot move a fingerprint boundary.
116	func (w *archiveWriter) policy(p Policy) {
117		for i := range policyFields {
118			f := &policyFields[i]
119			switch f.kind {
120			case policyFieldString, policyFieldOptionalString:
121				w.stringField(f.getString(p))
122			case policyFieldBool:
123				w.boolean(f.getBool(p))
124			}
125		}
126	}
127	
128	func (w *archiveWriter) policyList(policies []Policy) {
129		if policies == nil {
130			w.buf = append(w.buf, archiveTagNil)
131			return
132		}
133		w.buf = append(w.buf, archiveTagPresent)
134		w.u32(len(policies))
135		for _, p := range policies {
136			w.policy(p)
137		}
138	}
139	
140	// change writes the policy-change payload, or a single absence marker:
141	// VerifyAudit only ever accepts a change payload on a policy-change record
142	// and its absence otherwise, but the distinction is encoded explicitly so
143	// decode never has to reconstruct a shape. A present payload walks the
144	// single policy-change field table, so the archive's field order is the
145	// fingerprint's order by construction and every change field round trips.
146	func (w *archiveWriter) change(c *PolicyChange) {
147		if c == nil {
148			w.buf = append(w.buf, archiveTagNil)
149			return
150		}
151		w.buf = append(w.buf, archiveTagPresent)
152		for i := range changeFields {
153			f := &changeFields[i]
154			switch f.kind {
155			case changeFieldInt:
156				w.u32(f.getInt(c))
157			case changeFieldPolicyList:
158				w.policyList(f.getPolicies(c))
159			case changeFieldBool:
160				w.boolean(f.getBool(c))
161			}
162		}
163	}
164	
165	// decisionRecord writes the decision payload, or a single absence marker:
166	// VerifyAudit only ever accepts a decision payload on a decision record and
167	// its absence otherwise, but the distinction is encoded explicitly so decode
168	// never has to reconstruct a shape. A present payload walks the single
169	// decision field table, so the archive's field order is the fingerprint's
170	// order by construction and every request and decision field round trips.
171	func (w *archiveWriter) decisionRecord(d *DecisionRecord) {
172		if d == nil {
173			w.buf = append(w.buf, archiveTagNil)
174			return
175		}
176		w.buf = append(w.buf, archiveTagPresent)
177		for i := range decisionFields {
178			f := &decisionFields[i]
179			switch f.kind {
180			case decisionFieldString:
181				w.stringField(f.getString(d))
182			case decisionFieldStringList:
183				w.stringList(f.getList(d))
184			case decisionFieldBool:
185				w.boolean(f.getBool(d))
186			case decisionFieldInt:
187				w.u32(f.getInt(d))
188			}
189		}
190	}
191	
192	// EncodeAuditArchive serializes one complete audit export into savable
193	// bytes. org is the organization name, records is its complete chain from
194	// sequence 1 (a valid prefix ending at some historical sequence is enough,
195	// provided cp pins exactly that sequence), and cp is the checkpoint the
196	// caller separately retains. An organization with no records archives too:
197	// records is empty and cp is its sequence-0 genesis checkpoint.
198	//
199	// The whole material is validated exactly as VerifyAudit would before any
200	// bytes are returned: a missing organization is ErrMissingOrganization, and
201	// a missing, out-of-order or foreign record, modified content or checkpoint
202	// mismatch is ErrInvalidRange. On failure no archive bytes are returned.
203	// The checkpoint is carried in the archive for reference, but never stands
204	// in for the separately retained evidence: DecodeAuditArchive always
205	// validates against the checkpoint handed to it. The call is read-only:
206	// neither the records nor any service state are mutated and no audit record
207	// is appended.
208	func EncodeAuditArchive(org string, records []AuditRecord, cp Checkpoint) ([]byte, error) {
209		if org == "" {
210			return nil, ErrMissingOrganization
211		}
212		if err := VerifyAudit(org, records, cp); err != nil {
213			return nil, err
214		}
215	
216		pw := &archiveWriter{}
217		pw.stringField(org)
218		pw.u32(cp.EndSeq)
219		pw.stringField(cp.Fingerprint)
220		pw.u32(len(records))
221		for i := range records {
222			r := &records[i]
223			pw.stringField(r.Org)
224			pw.u32(r.Seq)
225			pw.stringField(r.Kind)
226			pw.change(r.Change)
227			pw.decisionRecord(r.Decision)
228			pw.stringField(r.PrevFingerprint)
229			pw.stringField(r.Fingerprint)
230		}
231		if pw.err != nil {
232			return nil, pw.err
233		}
234		payload := pw.buf
235	
236		out := make([]byte, 0, len(archiveMagic)+4+len(payload)+sha256.Size)
237		out = append(out, archiveMagic...)
238		var lenBuf [4]byte
239		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(payload)))
240		out = append(out, lenBuf[:]...)
241		out = append(out, payload...)
242		sum := sha256.Sum256(payload)
243		out = append(out, sum[:]...)
244		return out, nil
245	}
246	
247	// archiveReader walks one payload without copying string contents: string
248	// fields are backed by the payload slice itself, which is owned by the
249	// decoder and never returned, so callers cannot mutate the input through
250	// the result.
251	type archiveReader struct {
252		data []byte
253		pos  int
254		err  error
255	}
256	
257	func (r *archiveReader) need(n int) bool {
258		if r.err != nil {
259			return false
260		}
261		if n < 0 || r.pos > len(r.data)-n {
262			r.err = fmt.Errorf("%w: truncated archive payload", ErrInvalidArchive)
263			return false
264		}
265		return true
266	}
267	
268	func (r *archiveReader) marker() byte {
269		if !r.need(1) {
270			return 0
271		}
272		b := r.data[r.pos]
273		r.pos++
274		return b
275	}
276	
277	func (r *archiveReader) u32() int {
278		if !r.need(4) {
279			return 0
280		}
281		v := int(binary.BigEndian.Uint32(r.data[r.pos : r.pos+4]))
282		r.pos += 4
283		return v
284	}
285	
286	// boundedCount reads a count and proves at least minBytesPerItem bytes
287	// remain per item, so a hostile payload cannot drive a huge allocation
288	// with a count its body could never satisfy.
289	func (r *archiveReader) boundedCount(minBytesPerItem int) int {
290		n := r.u32()
291		if r.err != nil {
292			return 0
293		}
294		if n < 0 || uint64(n)*uint64(minBytesPerItem) > uint64(len(r.data)-r.pos) {
295			r.err = fmt.Errorf("%w: implausible list count %d", ErrInvalidArchive, n)
296			return 0
297		}
298		return n
299	}
300	
301	func (r *archiveReader) boolean() bool {
302		switch r.marker() {
303		case archiveTagBoolTrue:
304			return true
305		case archiveTagBoolFalse:
306			return false
307		default:
308			if r.err == nil {
309				r.err = fmt.Errorf("%w: invalid boolean marker", ErrInvalidArchive)
310			}
311			return false
312		}
313	}
314	
315	func (r *archiveReader) stringField() string {
316		n := r.u32()
317		if r.err != nil {
318			return ""
319		}
320		if !r.need(n) {
321			return ""
322		}
323		// Conversion copies the bytes, so the result never aliases the input.
324		s := string(r.data[r.pos : r.pos+n])
325		r.pos += n
326		return s
327	}
328	
329	func (r *archiveReader) stringList() []string {
330		switch r.marker() {
331		case archiveTagNil:
332			return nil
333		case archiveTagPresent:
334		default:
335			if r.err == nil {
336				r.err = fmt.Errorf("%w: invalid list marker", ErrInvalidArchive)
337			}
338			return nil
339		}
340		n := r.boundedCount(4) // each item carries at least one length word
341		if r.err != nil {
342			return nil
343		}
344		items := make([]string, n)
345		for i := range items {
346			items[i] = r.stringField()
347		}
348		return items
349	}
350	
351	func (r *archiveReader) policy() Policy {
352		// Read fields in the single table's (write and fingerprint) order. The
353		// fingerprint-optional ResourceID is still a mandatory, fixed field on
354		// the archive, so it is read for every policy including the empty one.
355		var p Policy
356		for i := range policyFields {
357			f := &policyFields[i]
358			switch f.kind {
359			case policyFieldString, policyFieldOptionalString:
360				f.setString(&p, r.stringField())
361			case policyFieldBool:
362				f.setBool(&p, r.boolean())
363			}
364		}
365		return p
366	}
367	
368	func (r *archiveReader) policyList() []Policy {
369		switch r.marker() {
370		case archiveTagNil:
371			return nil
372		case archiveTagPresent:
373		default:
374			if r.err == nil {
375				r.err = fmt.Errorf("%w: invalid policy list marker", ErrInvalidArchive)
376			}
377			return nil
378		}
379		// A policy writes six length words (five strings plus ResourceID) and
380		// one bool byte at minimum.
381		n := r.boundedCount(6*4 + 1)
382		if r.err != nil {
383			return nil
384		}
385		policies := make([]Policy, n)
386		for i := range policies {
387			policies[i] = r.policy()
388		}
389		return policies
390	}
391	
392	func (r *archiveReader) change() *PolicyChange {
393		switch r.marker() {
394		case archiveTagNil:
395			return nil
396		case archiveTagPresent:
397		default:
398			if r.err == nil {
399				r.err = fmt.Errorf("%w: invalid change payload marker", ErrInvalidArchive)
400			}
401			return nil
402		}
403		// Read fields in the single table's (write and fingerprint) order, so a
404		// field can never be restored into the wrong member or skipped.
405		c := &PolicyChange{}
406		for i := range changeFields {
407			f := &changeFields[i]
408			switch f.kind {
409			case changeFieldInt:
410				f.setInt(c, r.u32())
411			case changeFieldPolicyList:
412				f.setPolicies(c, r.policyList())
413			case changeFieldBool:
414				f.setBool(c, r.boolean())
415			}
416		}
417		return c
418	}
419	
420	func (r *archiveReader) decisionRecord() *DecisionRecord {
421		switch r.marker() {
422		case archiveTagNil:
423			return nil
424		case archiveTagPresent:
425		default:
426			if r.err == nil {
427				r.err = fmt.Errorf("%w: invalid decision payload marker", ErrInvalidArchive)
428			}
429			return nil
430		}
431		// Read fields in the single table's (write and fingerprint) order, so a
432		// field can never be restored into the wrong member or skipped.
433		d := &DecisionRecord{}
434		for i := range decisionFields {
435			f := &decisionFields[i]
436			switch f.kind {
437			case decisionFieldString:
438				f.setString(d, r.stringField())
439			case decisionFieldStringList:
440				f.setList(d, r.stringList())
441			case decisionFieldBool:
442				f.setBool(d, r.boolean())
443			case decisionFieldInt:
444				f.setInt(d, r.u32())
445			}
446		}
447		return d
448	}
449	
450	// DecodeAuditArchive reads one archive produced by EncodeAuditArchive and
451	// returns records that can be handed directly to RecheckDecisionOffline.
452	// org is the organization the caller expects, and cp is the checkpoint the
453	// caller independently retained; the checkpoint embedded in the file is
454	// never treated as evidence, so even an archive carrying a plausible
455	// checkpoint only validates against the one supplied here.
456	//
457	// A missing organization is ErrMissingOrganization. Unrecognized framing,
458	// truncation, a trailing second archive or any other extra byte, a bad
459	// checksum, and undecodable content are ErrInvalidArchive. Records that
460	// decode but are missing, out of order, foreign to the organization,
461	// modified (including a record after the one the caller intends to review)
462	// or mismatched with the supplied checkpoint fail the whole read with
463	// ErrInvalidRange. Failure returns no records. A successful read only
464	// proves the material matches the checkpoint: an original decision that
465	// disagrees with a recomputed one is reported later by offline review, not
466	// treated as archive damage. The result is detached from archive (mutating
467	// one never reaches the other), and the call is read-only.
468	func DecodeAuditArchive(archive []byte, org string, cp Checkpoint) ([]AuditRecord, error) {
469		if org == "" {
470			return nil, ErrMissingOrganization
471		}
472		magicLen := len(archiveMagic)
473		if len(archive) < magicLen+4+sha256.Size || string(archive[:magicLen]) != archiveMagic {
474			return nil, fmt.Errorf("%w: unrecognized audit archive", ErrInvalidArchive)
475		}
476		pos := magicLen
477		payloadLen := int(binary.BigEndian.Uint32(archive[pos : pos+4]))
478		pos += 4
479		checksumEnd := pos + payloadLen
480		if payloadLen < 0 || checksumEnd+sha256.Size != len(archive) {
481			// A short frame is truncation; bytes beyond the one frame (a
482			// concatenated second archive, junk appended to a good file) are a
483			// framing failure too.
484			return nil, fmt.Errorf("%w: truncated or trailing audit archive bytes", ErrInvalidArchive)
485		}
486		payload := archive[pos:checksumEnd]
487		sum := sha256.Sum256(payload)
488		if !bytes.Equal(sum[:], archive[checksumEnd:checksumEnd+sha256.Size]) {
489			return nil, fmt.Errorf("%w: checksum mismatch", ErrInvalidArchive)
490		}
491	
492		r := &archiveReader{data: payload}
493		embeddedOrg := r.stringField()
494		embeddedEndSeq := r.u32()
495		embeddedFingerprint := r.stringField()
496		// Every record writes two payload markers, a sequence word, two
497		// fingerprint length words and org/kind length words: 22 bytes even
498		// when every string is empty.
499		n := r.boundedCount(22)
500		if r.err != nil {
501			return nil, r.err
502		}
503		records := make([]AuditRecord, 0, n)
504		for i := 0; i < n; i++ {
505			var rec AuditRecord
506			rec.Org = r.stringField()
507			rec.Seq = r.u32()
508			rec.Kind = r.stringField()
509			rec.Change = r.change()
510			rec.Decision = r.decisionRecord()
511			rec.PrevFingerprint = r.stringField()
512			rec.Fingerprint = r.stringField()
513			records = append(records, rec)
514		}
515		if r.err != nil {
516			return nil, r.err
517		}
518		if r.pos != len(payload) {
519			return nil, fmt.Errorf("%w: %d unconsumed archive bytes", ErrInvalidArchive, len(payload)-r.pos)
520		}
521	
522		// Content checks reuse the exact audit-range validation the live export
523		// and offline review paths use, so an archive can never smuggle in a
524		// shape those entry points would reject.
525		if embeddedOrg != org {
526			return nil, fmt.Errorf("%w: archive organization %q does not match %q", ErrInvalidRange, embeddedOrg, org)
527		}
528		// The embedded checkpoint is informational; still, contradicting its own
529		// header means the payload was altered, and the authoritative check
530		// below always uses the caller's independently retained checkpoint.
531		if embeddedEndSeq != cp.EndSeq || embeddedFingerprint != cp.Fingerprint {
532			return nil, fmt.Errorf("%w: embedded checkpoint does not match the retained checkpoint", ErrInvalidRange)
533		}
534		if err := VerifyAudit(org, records, cp); err != nil {
535			return nil, err
536		}
537		return records, nil
538	}
539

