// encodeJSONEnvelope renders the fingerprint envelope for a record whose
// strings are all valid UTF-8 as the exact JSON object the historical
// encoding/json envelope produced: the envelope fields in table order,
// every string and payload encoded by encoding/json itself, and the two
// payload members dropped when absent exactly as their omitempty tags did.
// Walking the single record field table keeps this object in lockstep with
// the raw canonical encoding and the archive framing.
func encodeJSONEnvelope(r *AuditRecord) []byte {
    var buf []byte
    buf = append(buf, '{')
    first := true
    for i := range recordFields {
        f := &recordFields[i]
        if f.jsonKey == "" {
            continue
        }
        var (
            value []byte
            err   error
        )
        switch f.kind {
        case recordFieldString:
            value, err = json.Marshal(f.getString(r))
        case recordFieldInt:
            value, err = json.Marshal(f.getInt(r))
        case recordFieldChange:
            c := f.getChange(r)
            if c == nil {
                continue
            }
            value, err = json.Marshal(c)
        case recordFieldDecision:
            d := f.getDecision(r)
            if d == nil {
                continue
            }
            value, err = json.Marshal(d)
        }
        if err != nil {
            // All envelope values are plain, JSON-encodable values; a failure
            // here indicates a programming error, not user input.
            panic(fmt.Errorf("darksafe: audit envelope must encode: %w", err))
        }
        if !first {
            buf = append(buf, ',')
        }
        first = false
        buf = append(buf, '"')
        buf = append(buf, f.jsonKey...)
        buf = append(buf, '"', ':')
        buf = append(buf, value...)
    }
    return append(buf, '}')
}
