	getString   func(*AuditRecord) string
	setString   func(*AuditRecord, string)
	getInt      func(*AuditRecord) int
	setInt      func(*AuditRecord, int)
	getChange   func(*AuditRecord) *PolicyChange
	setChange   func(*AuditRecord, *PolicyChange)
