			marker := &DecisionRecord{Decision: Decision{Version: 8000 + i}}
			f.setDecision(&q, marker)
			if f.getDecision(&q) != marker {
				t.Fatalf("entry %d decision setter/getter do not round-trip", i)
			}
		}
